import { describe, expect, it } from 'vitest';
import { parseGpx } from './gpx';
import { gradeAt } from './grade';
import { detectClimbs } from './climbs';
import { buildProfile } from './profile';
import { speedFromPowerKmh } from '../physics/speed';
import manifest from '../../routes/manifest.json';
import rollingGpx from '../../routes/test-rolling.gpx?raw';
import mixedGpx from '../../routes/test-mixed.gpx?raw';
import type { Route } from './types';

// The routes in routes/ are generated by scripts/generate-routes.ts and committed.
// These assertions are the guard on that generator: if a tweak to it silently
// drifts a route off its stated distance or ascent, every downstream test that
// treats these as "the rolling one" and "the mixed one" quietly stops meaning
// what it says.

const rolling = parseGpx(rollingGpx);
const mixed = parseGpx(mixedGpx);

function entry(id: string) {
  const found = manifest.routes.find((route) => route.id === id);
  expect(found).toBeDefined();
  return found;
}

function grades(route: Route, everyM = 25): number[] {
  const out: number[] = [];
  for (let d = 0; d < route.totalDistanceM; d += everyM) out.push(gradeAt(route, d));
  return out;
}

function spacings(route: Route): number[] {
  return route.points.slice(1).map((point, i) => point.distM - (route.points[i]?.distM ?? 0));
}

describe('the bundled manifest', () => {
  it('lists every route with the fields the route list needs', () => {
    // The manifest grows as real GPX routes are added beside the generated ones, so this
    // asserts the shape of whatever is listed rather than a count that would go stale.
    expect(manifest.routes.length).toBeGreaterThanOrEqual(2);
    for (const route of manifest.routes) {
      expect(route.id).toBeTruthy();
      expect(route.name).toBeTruthy();
      expect(route.region).toBeTruthy();
      expect(route.file).toMatch(/\.gpx$/);
      expect(route.totalDistanceM).toBeGreaterThan(0);
      expect(route.totalAscentM).toBeGreaterThan(0);
    }
  });

  it('keeps the two generated routes, whatever else is added', () => {
    // A generator re-run must merge rather than overwrite; this fails if it clobbers.
    expect(entry('test-rolling')?.name).toMatch(/Rolling/);
    expect(entry('test-mixed')?.name).toMatch(/Mixed/);
  });

  it('agrees with what the parser reads out of the files', () => {
    expect(entry('test-rolling')?.totalDistanceM).toBe(Math.round(rolling.totalDistanceM));
    expect(entry('test-rolling')?.totalAscentM).toBe(Math.round(rolling.totalAscentM));
    expect(entry('test-mixed')?.totalDistanceM).toBe(Math.round(mixed.totalDistanceM));
    expect(entry('test-mixed')?.totalAscentM).toBe(Math.round(mixed.totalAscentM));
  });
});

describe('the rolling route', () => {
  it('is about 20 km with about 250 m of gain', () => {
    expect(rolling.totalDistanceM).toBeGreaterThan(19_500);
    expect(rolling.totalDistanceM).toBeLessThan(20_500);
    expect(rolling.totalAscentM).toBeGreaterThan(240);
    expect(rolling.totalAscentM).toBeLessThan(260);
  });

  it('has realistic GPS point spacing', () => {
    const gaps = spacings(rolling);
    expect(Math.min(...gaps)).toBeGreaterThan(10);
    expect(Math.max(...gaps)).toBeLessThan(20);
  });

  it('closes as a loop', () => {
    const first = rolling.points[0];
    const last = rolling.points.at(-1);
    expect(last?.lat).toBeCloseTo(first?.lat ?? 0, 6);
    expect(last?.lon).toBeCloseTo(first?.lon ?? 0, 6);
    expect(last?.eleM).toBeCloseTo(first?.eleM ?? 0, 1);
  });

  it('stays in the 2-5 % band with nothing near the clamp', () => {
    const absolute = grades(rolling)
      .map(Math.abs)
      .sort((a, b) => a - b);
    const p90 = absolute[Math.floor(0.9 * (absolute.length - 1))] ?? 0;
    expect(p90).toBeLessThanOrEqual(5.5);
    expect(Math.max(...absolute)).toBeLessThan(8);
  });

  it('moves past the 0.1 % write threshold on most steps, which is the point of it', () => {
    const series = grades(rolling, 15);
    const changed = series.filter((g, i) => i > 0 && Math.abs(g - (series[i - 1] ?? 0)) >= 0.1);
    expect(changed.length / series.length).toBeGreaterThan(0.7);

    // And never sits still for long: the flat stretches are turning points, not plateaus.
    let longestStill = 0;
    let still = 0;
    for (let i = 1; i < series.length; i += 1) {
      still = Math.abs((series[i] ?? 0) - (series[i - 1] ?? 0)) < 0.1 ? still + 1 : 0;
      longestStill = Math.max(longestStill, still);
    }
    expect(longestStill).toBeLessThan(15); // under 225 m; a real plateau would be far longer
  });

  it('has no dominant feature: no climb, but enough banded runs to shade', () => {
    expect(detectClimbs(rolling)).toEqual([]);
    expect(buildProfile(rolling).runs.length).toBeGreaterThan(10);
  });
});

describe('the mixed route', () => {
  it('is about 30 km with about 700 m of gain', () => {
    expect(mixed.totalDistanceM).toBeGreaterThan(29_000);
    expect(mixed.totalDistanceM).toBeLessThan(31_000);
    expect(mixed.totalAscentM).toBeGreaterThan(680);
    expect(mixed.totalAscentM).toBeLessThan(720);
  });

  it('has realistic GPS point spacing', () => {
    const gaps = spacings(mixed);
    expect(Math.min(...gaps)).toBeGreaterThan(10);
    expect(Math.max(...gaps)).toBeLessThan(20);
  });

  it('starts near enough flat', () => {
    expect(Math.max(...grades(mixed).slice(0, 4 * 25))).toBeLessThan(2);
  });

  it('has exactly one sustained climb of 4-5 km', () => {
    const climbs = detectClimbs(mixed);
    expect(climbs).toHaveLength(1);
    const climb = climbs[0];
    expect(climb?.lengthM).toBeGreaterThan(4000);
    expect(climb?.lengthM).toBeLessThan(5500);
    expect(climb?.gainM).toBeGreaterThan(300);
    expect(climb?.averageGradePercent).toBeGreaterThan(5.5);
    expect(climb?.averageGradePercent).toBeLessThan(8);
  });

  it('ramps to about 12 % near the summit, exercising the grade clamp', () => {
    expect(Math.max(...grades(mixed))).toBeGreaterThan(11);
    expect(buildProfile(mixed).bins.some((b) => b.band === '10+')).toBe(true);
  });

  it('descends steeply enough to coast well past 80 km/h at zero power', () => {
    // The route exists partly to exercise the fast end of the physics. It used to be
    // pinned to a clamp; now it is pinned to the balance the grade actually produces.
    const steepest = Math.min(...grades(mixed));
    expect(steepest).toBeLessThan(-13);
    expect(speedFromPowerKmh(0, steepest)).toBeGreaterThan(80);
  });

  it('shades every gradient band, so the chart legend has something in each', () => {
    const bands = new Set(buildProfile(mixed).runs.map((run) => run.band));
    expect([...bands].sort()).toEqual(['10+', '2-4', '4-7', '7-10']);
  });
});
